def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threats = 0
    urgent_opponents = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 500:
                rich_threats += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.75
    elif hp <= 4:
        danger += 0.45
    elif hp <= 6:
        danger += 0.2

    if no_water_days >= 2:
        danger += 0.8
    elif no_water_days >= 1:
        danger += 0.4

    late_game = 1.0 if day >= 8 else 0.0

    base = 18.0 + 28.0 * supply_pressure + 22.0 * danger + 8.0 * late_game

    if highest_prev >= 150:
        if hp >= 6 and no_water_days == 0 and supply >= 21:
            base = min(base, 16.0)
        else:
            base += 10.0 * supply_pressure + 6.0 * danger
    elif highest_prev >= 100:
        base = max(base, min(highest_prev * 0.42, 62.0))
    elif highest_prev > 0:
        base = max(base, min(highest_prev + 2.0, 58.0))
    else:
        base = max(base, 24.0)

    if rich_threats >= 2 and supply <= 18:
        base += 8.0
    if urgent_opponents >= 2 and supply <= 18:
        base += 5.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(base, 72.0 + 18.0 * supply_pressure)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(base, 48.0 + 14.0 * supply_pressure)
    else:
        bid = base

    soft_cap = budget
    if day <= 3:
        soft_cap = min(soft_cap, 95.0)
    elif day <= 6:
        soft_cap = min(soft_cap, 110.0)
    else:
        soft_cap = min(soft_cap, 130.0)

    if hp >= 7 and no_water_days == 0 and supply >= 22:
        soft_cap = min(soft_cap, 35.0)

    bid = min(bid, soft_cap)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids (immediate reaction only)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure heuristic: lower supply => higher competition
    # Expected number of water units relative to requirement
    supply_units = supply / float(WATER_REQ) if WATER_REQ else 0.0
    # Map to a competition multiplier in [0.9, 1.25]
    if supply <= MIN_SUPPLY:
        comp_mult = 1.25
    elif supply >= MAX_SUPPLY:
        comp_mult = 0.9
    else:
        # linear interpolation between bounds
        t = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
        comp_mult = 1.25 - 0.35 * t

    # Base target bid: track their equilibrium bids (~150) but keep budget safe
    # If their highest bid was very high, we must match more.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(avg_prev_bid, highest_prev_bid * 0.95)
    else:
        target = max(avg_prev_bid * 0.85, DAILY_SALARY * 0.55)

    # Adjust for our urgency
    urgency = 0.0
    if hp <= 2:
        urgency += 0.35
    if no_water_days >= 2:
        urgency += 0.25
    if hp <= 3:
        urgency += 0.15

    target = target * (1.0 + urgency) * comp_mult

    # Cap: don't overbid beyond a fraction of budget; also avoid bidding above typical max
    # Budget fraction increases when low HP.
    if hp <= 2:
        budget_cap_frac = 0.95
    elif hp <= 4:
        budget_cap_frac = 0.85
    else:
        budget_cap_frac = 0.70

    max_bid_allowed = budget * budget_cap_frac

    # Soft upper cap near observed opponent max (approx 173.5) but still bounded by budget
    soft_cap = 180.0
    bid = min(float(target), soft_cap, float(max_bid_allowed), budget)

    # Ensure non-negative and at least 1 when we can afford it
    if bid < 1.0:
        bid = 0.0 if budget < 1.0 else 1.0

    return float(bid)

